#!/usr/bin/env python3
"""Regenerate include/workspace/exports.h and jit_exports.inc from EXPORTC in qlogo/exports/exports*.cpp."""

import re
import subprocess
from pathlib import Path

HEADER = """#ifndef WORKSPACE_EXPORTS_H
#define WORKSPACE_EXPORTS_H

// DO NOT EDIT THIS FILE!
// Any changes to this file will not last long!
// It was generated by update_exports_header.py.
// See util/update_exports_header.py for details.

#include "compiler_types.h"
#include "workspace/exports_internal.h"

"""

FOOTER = """#endif // WORKSPACE_EXPORTS_H
"""

def _repo_root() -> Path:
    result = subprocess.run(
        ["git", "rev-parse", "--show-toplevel"],
        capture_output=True,
        text=True,
        check=True,
        cwd=Path(__file__).resolve().parent,
    )
    return Path(result.stdout.strip())

REPO_ROOT = _repo_root()
HEADER_PATH = REPO_ROOT / "include" / "workspace" / "exports.h"
JIT_EXPORTS_PATH = REPO_ROOT / "include" / "workspace" / "jit_exports.inc"
SOURCE_GLOB = "qlogo/exports/exports*.cpp"

JIT_EXPORTS_HEADER = """// DO NOT EDIT THIS FILE!
// Any changes to this file will not last long!
// It was generated by update_exports_header.py.
// See util/update_exports_header.py for details.
//
// X-macro list of EXPORTC definitions for ORC absolute-symbol registration.
// Define JIT_EXPORT(fn) before including this file.

"""

EXPORT_DEF_RE = re.compile(r"^EXPORTC\b(.*?)\s*([{;])", re.MULTILINE | re.DOTALL)
EXPORT_NAME_RE = re.compile(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*\(")


def extract_export_definition_names(source_text: str) -> list[str]:
    """Names of EXPORTC *definitions* (those whose signature is followed by '{')."""
    names = []
    for match in EXPORT_DEF_RE.finditer(source_text):
        body, terminator = match.group(1), match.group(2)
        if terminator != "{":
            continue
        name_match = EXPORT_NAME_RE.search(body)
        if not name_match:
            raise SystemExit(f"Could not parse EXPORTC name from:{body}")
        names.append(name_match.group(1))
    return names


def extract_export_declarations(source_text: str) -> list[str]:
    """Collect EXPORTC signatures from source, normalize to one-line declarations."""
    declarations = []
    for match in EXPORT_DEF_RE.finditer(source_text):
        sig = "EXPORTC" + match.group(1)
        if "//" in sig:
            sig = sig.split("//", 1)[0]
        sig = re.sub(r"[ \t]*\n[ \t]*", " ", sig).rstrip()
        declarations.append(sig + ";\n")
    return declarations


def main() -> None:
    source_paths = sorted(REPO_ROOT.glob(SOURCE_GLOB))
    if not source_paths:
        raise SystemExit(f"No export sources matched {SOURCE_GLOB}")

    declarations = []
    jit_lines = [JIT_EXPORTS_HEADER]
    seen = set()
    for source_path in source_paths:
        declarations.append("\n")
        declarations.append("//  -------------------------------------------------------------------\n")
        declarations.append(f"//  {source_path.name}\n")
        declarations.append("//  -------------------------------------------------------------------\n")
        declarations.append("\n")
        source_text = source_path.read_text(encoding="utf-8")
        declarations.extend(extract_export_declarations(source_text))
        for name in extract_export_definition_names(source_text):
            if name in seen:
                continue
            seen.add(name)
            jit_lines.append(f"JIT_EXPORT({name})\n")

    HEADER_PATH.write_text(HEADER + "".join(declarations) + FOOTER, encoding="utf-8")
    JIT_EXPORTS_PATH.write_text("".join(jit_lines), encoding="utf-8")


if __name__ == "__main__":
    main()
